/**
 * CONFIGURACAO DO NEWSLETTER DE NOTICIAS
 * ---------------------------------------
 * Edite este node para adicionar/remover fontes RSS, temas (topics) e filtros.
 *
 * Cada tema em `topicsMeta` pode ter um filtro opcional:
 *   - mode: "include" -> so passam noticias que mencionem uma das keywords
 *   - mode: "exclude" -> descarta noticias que mencionem uma das keywords
 *   - filter: null     -> sem filtro, todas as noticias do tema passam
 *
 * Exemplo (Acoes): so chegam noticias sobre as empresas/tickers listados.
 * Para adicionar uma acao nova, inclua o nome/ticker no array `keywords`.
 * Para remover, apague o item do array. O mesmo vale para qualquer outro tema.
 */

const topicsMeta = {
  brasil: { label: '🇧🇷 Brasil', filter: null },
  mundo: { label: '🌍 Mundo', filter: null },
  economia: { label: '💰 Economia', filter: null },
  tecnologia: { label: '💻 Tecnologia', filter: null },
  acoes: {
    label: '📈 Acoes e Mercado',
    filter: {
      mode: 'include',
      keywords: [
        'Petrobras', 'PETR4',
        'Vale', 'VALE3',
        'Itau', 'ITUB4',
        'Bradesco', 'BBDC4',
        'Banco do Brasil', 'BBAS3',
        'Magazine Luiza', 'MGLU3',
        'Ambev', 'ABEV3',
        'Nubank', 'ROXO34',
        'B3', 'Ibovespa'
      ]
    }
  }
};

// Ordem em que os temas aparecem no e-mail final
const topicOrder = ['brasil', 'mundo', 'economia', 'tecnologia', 'acoes'];

// Lista de feeds RSS. Cada feed pertence a um dos temas acima (`topic`).
const feeds = [
  { topic: 'brasil', source: 'G1', url: 'https://g1.globo.com/rss/g1/' },
  { topic: 'brasil', source: 'Folha - Ultimas', url: 'https://feeds.folha.uol.com.br/emcimadahora/rss091.xml' },
  { topic: 'brasil', source: 'Estadao', url: 'https://www.estadao.com.br/arc/outboundfeeds/rss/' },

  { topic: 'mundo', source: 'BBC Brasil (Mundo)', url: 'https://www.bbc.com/portuguese/index.xml' },
  { topic: 'mundo', source: 'BBC World', url: 'http://feeds.bbci.co.uk/news/world/rss.xml' },
  { topic: 'mundo', source: 'The Guardian - World', url: 'https://www.theguardian.com/world/rss' },
  { topic: 'mundo', source: 'NYT - World', url: 'https://rss.nytimes.com/services/xml/rss/nyt/World.xml' },

  { topic: 'economia', source: 'Folha - Mercado', url: 'https://feeds.folha.uol.com.br/mercado/rss091.xml' },
  { topic: 'economia', source: 'G1 - Economia', url: 'https://g1.globo.com/rss/g1/economia/' },

  { topic: 'tecnologia', source: 'G1 - Tecnologia', url: 'https://g1.globo.com/rss/g1/tecnologia/' },
  { topic: 'tecnologia', source: 'The Verge', url: 'https://www.theverge.com/rss/index.xml' },

  { topic: 'acoes', source: 'InfoMoney - Mercados', url: 'https://www.infomoney.com.br/mercados/feed/' },
  { topic: 'acoes', source: 'Folha - Mercado', url: 'https://feeds.folha.uol.com.br/mercado/rss091.xml' }
];

return feeds.map(feed => ({
  json: {
    ...feed,
    topicsMeta,
    topicOrder
  }
}));

// Junta cada noticia (vinda do RSS Feed Read) com a config do feed que a
// originou (node "Config"), e aplica o filtro do tema (include/exclude).

const results = [];
const inputItems = $input.all();

for (let i = 0; i < inputItems.length; i++) {
  const article = inputItems[i].json;
  const feedMeta = $('Config').itemMatching(i).json;
  const topicInfo = feedMeta.topicsMeta[feedMeta.topic];

  const title = (article.title || '').trim();
  const rawSummary = article.contentSnippet || article.content || article.summary || '';
  const summary = rawSummary.replace(/<[^>]*>/g, '').trim().slice(0, 300);
  const link = article.link || article.guid;
  const pubDate = article.pubDate || article.isoDate || new Date().toISOString();

  if (!title || !link) continue;

  if (topicInfo.filter) {
    const haystack = (title + ' ' + summary).toLowerCase();
    const matches = topicInfo.filter.keywords.some(k => haystack.includes(k.toLowerCase()));
    const passes = topicInfo.filter.mode === 'include' ? matches : !matches;
    if (!passes) continue;
  }

  results.push({
    json: {
      topic: feedMeta.topic,
      topicLabel: topicInfo.label,
      topicOrder: feedMeta.topicOrder,
      source: feedMeta.source,
      title,
      link,
      summary,
      pubDate
    }
  });
}

return results;

// Remove noticias ja enviadas em execucoes anteriores (usando a memoria
// estatica do workflow) e ignora noticias fora da janela de tempo definida.

const HOURS_WINDOW = 30; // margem de seguranca sobre o intervalo do Schedule Trigger
const MAX_SEEN_LINKS = 3000; // limite de itens guardados na memoria

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.seenLinks)) staticData.seenLinks = [];
const seen = new Set(staticData.seenLinks);

const cutoff = Date.now() - HOURS_WINDOW * 60 * 60 * 1000;
const fresh = [];

for (const item of $input.all()) {
  const { link, pubDate } = item.json;
  const pubTime = new Date(pubDate).getTime();

  if (seen.has(link)) continue;
  if (!Number.isNaN(pubTime) && pubTime < cutoff) continue;

  fresh.push(item);
  seen.add(link);
}

staticData.seenLinks = Array.from(seen).slice(-MAX_SEEN_LINKS);

return fresh;

const items = $input.all().map(i => i.json);

const order = items[0]?.topicOrder || ['brasil', 'mundo', 'economia', 'tecnologia', 'acoes'];

const groups = {};
for (const it of items) {
  if (!groups[it.topic]) groups[it.topic] = { label: it.topicLabel, articles: [] };
  groups[it.topic].articles.push(it);
}

const today = new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' });

let html = `
<div style="font-family: Arial, sans-serif; max-width: 640px; margin: 0 auto; color:#222;">
  <h1 style="font-size:22px;">📰 Noticias de hoje - ${today}</h1>
`;

let hasNews = false;

for (const topic of order) {
  const group = groups[topic];
  if (!group || group.articles.length === 0) continue;
  hasNews = true;

  html += `<h2 style="font-size:18px; border-bottom:2px solid #eee; padding-bottom:4px;">${group.label}</h2><ul style="padding-left:18px;">`;
  for (const a of group.articles) {
    html += `
      <li style="margin-bottom:14px;">
        <a href="${a.link}" style="font-weight:bold; text-decoration:none; color:#1a0dab;">${a.title}</a>
        <div style="font-size:12px; color:#777;">${a.source}</div>
        <div style="font-size:13px; color:#444;">${a.summary}</div>
      </li>`;
  }
  html += `</ul>`;
}

if (!hasNews) {
  html += `<p>Nenhuma noticia nova encontrada hoje.</p>`;
}

html += `</div>`;

return [{
  json: {
    html,
    subject: `📰 Noticias do dia - ${today}`,
    hasNews
  }
}];
